package mapfile

import (
	"bytes"
	"compress/gzip"
	"encoding/base64"
	"encoding/binary"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"reflect"
	"testing"
)

// update writes the fixtures missing from testdata: go test ./internal/mapfile/ -run TestFixtures -update.
// It never rewrites one that exists, since a fixture regenerated by the reader it tests checks nothing.
var update = flag.Bool("update", false, "write the missing testdata/v<n>.wmap fixtures")

// writeVersion writes m as a version v stream, laid out as that version had it: version 1 the
// heights and its two splats, version 2 on the weights and slot table, then each version's tail in
// turn (holes 3, liquids 4, chunk data 5, shadows 6; 7 the layout of 6, its change in the header). It is the format's history kept apart from
// Write, so the fixtures it made stay what each version wrote.
func writeVersion(w io.Writer, m *MapData, v uint32) error {
	if v < 1 || v > 7 {
		return fmt.Errorf("writeVersion knows versions 1 to 7, not %d", v)
	}
	hdr, err := json.Marshal(&m.Header)
	if err != nil {
		return err
	}
	var errs []error
	dec := func(name, s string) []byte {
		b, err := base64.StdEncoding.DecodeString(s)
		if err != nil {
			errs = append(errs, fmt.Errorf("%s: %w", name, err))
		}
		return b
	}
	sized := func(b []byte) []byte {
		var n [4]byte
		binary.LittleEndian.PutUint32(n[:], uint32(len(b)))
		return append(n[:], b...)
	}
	var pre [12]byte
	copy(pre[:4], Magic)
	binary.LittleEndian.PutUint32(pre[4:8], v)
	binary.LittleEndian.PutUint32(pre[8:12], uint32(len(hdr)))
	parts := [][]byte{pre[:], hdr, dec("heights", m.Heights)}
	if v == 1 {
		parts = append(parts, dec("splatA", m.SplatA), dec("splatB", m.SplatB))
	} else {
		parts = append(parts, dec("weights", m.Weights), dec("chunkSlots", m.ChunkSlots))
		if v >= 3 {
			parts = append(parts, dec("holes", m.Holes))
		}
		if v >= 4 {
			parts = append(parts, sized(dec("liquids", m.Liquids)))
		}
		if v >= 5 {
			parts = append(parts, dec("areaIds", m.AreaIDs), dec("chunkFlags", m.ChunkFlags), dec("noEffect", m.NoEffect))
		}
		if v >= 6 {
			parts = append(parts, sized(dec("shadows", m.Shadows)))
		}
	}
	if err := errors.Join(errs...); err != nil {
		return err
	}
	gz := gzip.NewWriter(w)
	for _, p := range parts {
		if _, err := gz.Write(p); err != nil {
			return err
		}
	}
	return gz.Close()
}

// fixtureMap is the 16-cell map the version v fixture holds, as Read must return it: sample(16) with
// the blobs version v had, and for version 1 its two splats and eight layer textures instead of the
// weights and slot table.
func fixtureMap(v int) *MapData {
	m := sample(16)
	m.Version = v
	if v == 1 {
		w, _ := base64.StdEncoding.DecodeString(m.Weights)
		b := make([]byte, len(w))
		for i := range w {
			b[i] = w[len(w)-1-i]
		}
		m.SplatA, m.SplatB = m.Weights, base64.StdEncoding.EncodeToString(b)
		m.Weights, m.ChunkSlots, m.Palette = "", "", nil
		m.LayerTextures = []string{"", `Tileset\Elwynn\ElwynnDirtBase.blp`}
	}
	if v < 3 {
		m.Holes = ""
	}
	if v < 4 {
		m.Liquids = ""
	}
	if v < 5 {
		m.AreaIDs, m.ChunkFlags, m.NoEffect = "", "", ""
	}
	if v < 6 {
		m.Shadows = ""
	}
	return m
}

func fixturePath(v int) string { return filepath.Join("testdata", fmt.Sprintf("v%d.wmap", v)) }

// gunzip is a .wmap stream's bytes before compression, so two writes compare by layout, not by how
// gzip packed them.
func gunzip(t *testing.T, b []byte) []byte {
	t.Helper()
	gz, err := gzip.NewReader(bytes.NewReader(b))
	if err != nil {
		t.Fatal(err)
	}
	raw, err := io.ReadAll(gz)
	if err != nil {
		t.Fatal(err)
	}
	return raw
}

// body is an uncompressed stream without its JSON header: the version, then the blobs. The header is
// left out so that a new optional header field, which needs no new version, doesn't fail the layout
// check; the header's own round trip is the header comparison.
func body(t *testing.T, raw []byte) []byte {
	t.Helper()
	if len(raw) < 12 {
		t.Fatalf("stream of %d bytes", len(raw))
	}
	n := int(binary.LittleEndian.Uint32(raw[8:12]))
	if len(raw) < 12+n {
		t.Fatalf("header of %d bytes in a stream of %d", n, len(raw))
	}
	return append(append([]byte{}, raw[4:8]...), raw[12+n:]...)
}

// blobs are a map's binary fields by name, for comparing two reads blob by blob.
func blobs(m *MapData) map[string]string {
	return map[string]string{
		"heights": m.Heights, "weights": m.Weights, "chunkSlots": m.ChunkSlots, "holes": m.Holes, "liquids": m.Liquids,
		"areaIds": m.AreaIDs, "chunkFlags": m.ChunkFlags, "noEffect": m.NoEffect, "shadows": m.Shadows,
	}
}

// Every version's committed fixture (testdata/v1.wmap to v<Version>.wmap, a 16-cell map written once
// as that version laid it out) opens with the header and blobs it was written with, and none it
// lacked (#545). A reader that drops, reorders or misreads a tail blob fails here even when Write and
// Read change together, which TestRoundTrip cannot see. Each fixture from version 2 on saved again at
// Version reads back with the same blobs; version 1 is converted by the frontend before it can be
// saved. A format change that doesn't bump Version fails the last check: Write must still lay out
// the current fixture byte for byte.
func TestFixtures(t *testing.T) {
	for v := 1; v <= Version; v++ {
		path := fixturePath(v)
		raw, err := os.ReadFile(path)
		if errors.Is(err, os.ErrNotExist) && *update {
			var buf bytes.Buffer
			if err := writeVersion(&buf, fixtureMap(v), uint32(v)); err != nil {
				t.Fatalf("v%d: %v", v, err)
			}
			if err := os.MkdirAll("testdata", 0o755); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(path, buf.Bytes(), 0o644); err != nil {
				t.Fatal(err)
			}
			t.Logf("wrote %s", path)
			raw = buf.Bytes()
		} else if err != nil {
			t.Fatalf("v%d: %v (a new Version needs its fixture: go test ./internal/mapfile/ -run TestFixtures -update)", v, err)
		}
		got, err := Read(bytes.NewReader(raw))
		if err != nil {
			t.Fatalf("v%d: read: %v", v, err)
		}
		want := fixtureMap(v)
		if !reflect.DeepEqual(got.Header, want.Header) {
			t.Errorf("v%d: header\n got %+v\nwant %+v", v, got.Header, want.Header)
		}
		got.Header = want.Header
		if !reflect.DeepEqual(got, want) {
			for name, b := range blobs(want) {
				if blobs(got)[name] != b {
					t.Errorf("v%d: %s differs: read %d base64 chars, want %d", v, name, len(blobs(got)[name]), len(b))
				}
			}
			t.Errorf("v%d: read version %d, splatA %d chars, splatB %d chars", v, got.Version, len(got.SplatA), len(got.SplatB))
			continue
		}
		if v == 1 {
			continue
		}
		var buf bytes.Buffer
		if err := Write(&buf, got); err != nil {
			t.Fatalf("v%d: save at version %d: %v", v, Version, err)
		}
		again, err := Read(&buf)
		if err != nil {
			t.Fatalf("v%d: read the save: %v", v, err)
		}
		if again.Version != Version {
			t.Errorf("v%d: saved as version %d, want %d", v, again.Version, Version)
		}
		for name, b := range blobs(want) {
			if b != "" && blobs(again)[name] != b {
				t.Errorf("v%d: %s changed across a save at version %d", v, name, Version)
			}
		}
	}
	cur, err := os.ReadFile(fixturePath(Version))
	if err != nil {
		return
	}
	var buf bytes.Buffer
	if err := Write(&buf, fixtureMap(Version)); err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(body(t, gunzip(t, buf.Bytes())), body(t, gunzip(t, cur))) {
		t.Errorf("Write no longer lays out %s: a change to the format needs a new Version, its fixture and its case in writeVersion", fixturePath(Version))
	}
}
